    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base score is the residual space after placement.
    // Smaller post_residual is generally better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if the remaining space is too small to fit typical future items
    // but large enough to be wasteful, we penalize it.
    // We use a quadratic penalty centered around 5-15, which are notoriously difficult gaps.
    let dead_space_penalty = (10.0 - post_res).powi(2) * (1.0 - progress);
    score += dead_space_penalty;

    // Lookahead coupling: If next_item_size exists, penalize bins that cannot fit it.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            score += (next_item_size as f64 - post_res) * 1.5;
        }
    }

    // Adaptivity: As the stream progresses, prioritize closing bins (lower mean_residual) 
    // to consolidate space, penalizing bins that deviate significantly from the mean.
    let deviation = (post_res - mean_residual).abs();
    score += deviation * progress;

    // Favor opening a new bin only if the current fit is extremely poor (Best Fit vs First Fit trade-off).
    // If this is a new bin (bin_residual == bin_capacity), set a threshold cost.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, reduced slightly as we approach the end
        // to ensure we don't leave many partially filled bins.
        score = 25.0 + (progress * 15.0);
    } else {
        // If it's an existing bin, reduce score if it's the only bin that fits the item,
        // preventing the heuristic from forcing a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual represents the "wasted" space in the bin after placement.
    // We aim for Best Fit (minimizing post_residual) but with heavy penalties for 
    // creating "unusable" small gaps (e.g., < 10) and rewards for fitting lookahead items.

    let mut score = post_residual as f64;

    // 1. Penalty for creating small, unusable slivers (dead space)
    // If post_residual is small but > 0, it's often better to have left it empty or filled it perfectly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - (post_residual as f64 * 2.5);
    }

    // 2. Lookahead Logic: If next_item_size fits in the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Global State: If we are late in the stream, favor tighter packing (lower residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual - post_residual as f64);

    // 4. New Bin Logic: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the current open bins are all "bad" fits.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is high, but scales with the number of open bins.
        // If we have many bins open, opening another is less costly than if we have few.
        score += 45.0 - (open_bins_count as f64 * 0.5);
    }

    // 5. Fitting Constraint: If this is the only bin that can fit the item, 
    // don't penalize it too harshly to avoid forcing a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large residual space left over (standard logic)
    // We want post_residual to be as small as possible.
    score += (post_residual as f64).powf(1.1);

    // 2. Harmonic Class Logic: Reward placements that leave a residual which is a multiple 
    // of common item sizes (e.g., 20, 25, 33) to minimize fragmentation.
    let remainder_score = (post_residual % 20) as f64;
    score += remainder_score * 0.5;

    // 3. Lookahead Synergy: If the next item fits into the post-placement residual, 
    // heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 4. New Bin Thresholding: If this is a new bin (bin_residual == bin_capacity),
    // only choose it if it is strictly necessary or if the current best fit is "toxic".
    if bin_residual == bin_capacity {
        // High penalty to open new bins unless they are the only option or 
        // existing bins are highly fragmented.
        score += 45.0; 
        if fitting_bins_count == 0 {
            score -= 50.0; // Force opening a new bin if nothing else fits
        }
    }

    // 5. Global Density Awareness: As the stream progresses, favor packing tighter.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64) * 0.1;

    // 6. Mean Residual Balancing: Avoid creating bins that deviate significantly 
    // from the average residual of existing bins to keep bin states uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

