    // Target: Minimize score.
    // Archetype: Aggressive 2-step lookahead matching.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalty for opening a new bin is high, but scales down if fitting options are poor
        // or if we are nearing the end of the stream.
        score = 25.0 + (100.0 * (step_index as f64 / total_items as f64));

        // If we have very few open bins, we are more willing to open a new one to keep space density high.
        if open_bins_count < 3 {
            score -= 10.0;
        }
    } else {
        // Reward placements that leave a residual close to the next_item_size (Best Fit Lookahead)
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Perfect alignment bonus
                let diff = (post_residual - next_item_size) as f64;
                score -= (50.0 - diff).max(0.0) * 0.8;
            } else {
                // Penalty for making the bin unable to fit the next item
                score += 30.0;
            }
        }

        // Penalty for leaving "dead space" that is smaller than the smallest typical item (e.g., < 10)
        if post_residual < 10 && post_residual > 0 {
            score += 40.0;
        }

        // Favor bins that are already "tight" compared to the mean residual to consolidate space
        let tightness_factor = (post_residual as f64 - mean_residual).abs();
        score += tightness_factor * 0.2;
    }

    // If this is the last chance to fit the item in an existing bin, prioritize it heavily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    score
}

