    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is too small to fit the smallest possible 
    // items (statistically ~10), it is "wasted" space. Penalize gaps < 10 heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Best-Fit/First-Fit Pressure: If we have multiple fitting bins, we prefer 
