    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // 3. Lookahead Optimization: If the next item is large, avoid leaving a residual
    // that is just slightly too small to fit it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 4. Open Bins Management: Penalize opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy pressure 
    // based on how many bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5);
    }

    // 5. Global Efficiency: If the current bin is very empty (low residual), 
    // penalize using it to keep it available for potentially larger items later.
    if bin_residual > 80 {
        score += 10.0;
    }

    score
